# generated by build/adapters.py from plugins/neva-core and plugins/neva-library, do not edit
"""quality_gate: deterministic checks a candidate must pass before it becomes a proposal.

Standard library only, no model call, no network. instinct-cli.py runs every candidate through
`check()` before writing it to a proposal file. A candidate that fails is parked with the reasons,
never shown as a proposal and never deleted. The four checks:

  restates      the lesson is already written down: a paragraph in the rules folder, a line in a
                memory index file, a skill or command description, a global instinct, or another
                candidate already accepted in this run
  vague         it names a tool or a count of tool use, not a behaviour
  thin          its evidence does not span two sessions on two different days
  dormant       none of its projects had any activity in the last ACTIVE_DAYS days

Restatement is token overlap on instinct_match stems: the overlap coefficient (shared stems over
the smaller set) must reach OVERLAP_THRESHOLD with at least MIN_SHARED stems in common. Calibrated
on a labelled queue of 110 candidates (54 judged already written down, 33 judged empty, 18 judged
worth asking about, 5 lessons): at 0.6 with 3 shared stems it flags 18 of the 54 already-written
items and 6 of the 33 empty ones, and none of the items worth keeping, merging or gating. Lower
thresholds start flagging items worth keeping (0.5 flags 6 of 18); higher ones catch fewer
restatements without sparing any good item. Token overlap cannot see a restatement in other
words; the other three checks carry the rest.
"""
import glob
import os
import re
from datetime import date, datetime

import instinct_match

OVERLAP_THRESHOLD = 0.6
MIN_SHARED = 3
MIN_SESSIONS = 2
MIN_DAYS = 2
ACTIVE_DAYS = 30
MIN_BEHAVIOUR_STEMS = 3

# Tool names and the words of a usage count. A lesson whose action is left with fewer than
# MIN_BEHAVIOUR_STEMS stems once these are removed says which tool was used, not what to do.
# Tool names that are also plain verbs (read, edit, write) stay out: "read the whole file before
# editing it" is a behaviour.
TOOL_WORDS = frozenset(instinct_match.tokens("""
bash grep glob multiedit webfetch websearch todowrite notebookedit subagent tool tools
call calls called calling invocation invocations invoke invoked
time times count counts observation observations observed session sessions frequently often
repeatedly always usually consistently prefer preferred preference
"""))
_COUNT = re.compile(r"\b\d+\s+(?:times|calls|tool calls|invocations|uses|observations)\b", re.I)
_SESSION = re.compile(r"\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b", re.I)
_DAY = re.compile(r"\b(\d{4}-\d{2}-\d{2})\b")


def _stems(text):
    return set(instinct_match.tokens(text))


def _action(inst):
    m = re.search(r"## Action\s*\n\s*(.+?)(?:\n\n|\n##|$)", inst.get("content", "") or "", re.S)
    return m.group(1).strip() if m else ""


def lesson_text(inst):
    return f"{inst.get('trigger', '')} {_action(inst)}"


# ------------------------------------------------------------------ corpus of what is written down

def _paragraphs(text):
    for part in re.split(r"\n\s*\n|\n(?=[-*] |#)", text):
        part = part.strip()
        if part:
            yield part


def _description(path):
    try:
        with open(path, encoding="utf-8", errors="replace") as fh:
            head = fh.read(4000)
    except OSError:
        return ""
    m = re.search(r"^description:\s*(.+)$", head, re.M)
    return m.group(1).strip().strip('"\'') if m else ""


def load_corpus(rules_dirs=(), memory_dirs=(), skill_roots=(), extra=()):
    """[(source label, stems)] for every unit of text that already says something.

    rules_dirs   every *.md below, split into paragraphs, headings and bullets
    memory_dirs  MEMORY.md and every INDEX.md below, one unit per `- ` line
    skill_roots  config folders: skills/*/SKILL.md and commands/**/*.md descriptions, plus the same
                 inside installed plugins (plugins/cache/<market>/<plugin>/<version>/)
    extra        (label, text) pairs, for global instincts
    Missing folders are skipped: an empty corpus restates nothing."""
    units, seen_files = [], set()

    def add(label, text):
        stems = _stems(text)
        if len(stems) >= MIN_SHARED:
            units.append((label, stems))

    def once(path):
        real = os.path.realpath(path)
        if real in seen_files:
            return False
        seen_files.add(real)
        return True

    for root in rules_dirs:
        for path in sorted(glob.glob(os.path.join(root, "**", "*.md"), recursive=True)):
            if not once(path):
                continue
            try:
                text = open(path, encoding="utf-8", errors="replace").read()
            except OSError:
                continue
            for part in _paragraphs(text):
                add(f"rule {os.path.relpath(path, root)}", part)
    for root in memory_dirs:
        paths = [os.path.join(root, "MEMORY.md")] + glob.glob(os.path.join(root, "**", "INDEX.md"), recursive=True)
        for path in sorted(paths):
            if not os.path.isfile(path) or not once(path):
                continue
            for line in open(path, encoding="utf-8", errors="replace").read().splitlines():
                if line.startswith("- "):
                    add(f"memory index {os.path.relpath(path, root)}", line)
    for root in skill_roots:
        patterns = ["skills/*/SKILL.md", "commands/**/*.md",
                    "plugins/cache/*/*/*/skills/*/SKILL.md", "plugins/cache/*/*/*/commands/**/*.md"]
        for pattern in patterns:
            for path in sorted(glob.glob(os.path.join(root, pattern), recursive=True)):
                if not once(path):
                    continue
                desc = _description(path)
                if desc:
                    add(f"skill or command {os.path.relpath(path, root)}", desc)
    for label, text in extra:
        add(label, text)
    return units


def restates(stems, corpus, skip_labels=()):
    """(label, score) of the first corpus unit this lesson restates, else None."""
    if not stems:
        return None
    best = None
    for label, unit in corpus:
        if label in skip_labels:
            continue
        shared = len(stems & unit)
        if shared < MIN_SHARED:
            continue
        score = shared / min(len(stems), len(unit))
        if score >= OVERLAP_THRESHOLD and (best is None or score > best[1]):
            best = (label, score)
    return best


# ------------------------------------------------------------------ the other three checks

def vague(members):
    """A reason when the lesson names a tool or a count instead of a behaviour, else ''."""
    for inst in members:
        action = _action(inst)
        if _COUNT.search(action):
            return f"its action states a count of tool use ('{_COUNT.search(action).group(0)}'), not a behaviour"
        left = _stems(action) - TOOL_WORDS
        if len(left) < MIN_BEHAVIOUR_STEMS:
            return (f"its action names a tool, not a behaviour: {len(left)} specific word(s) left once tool names "
                    f"and counts are removed, {MIN_BEHAVIOUR_STEMS} needed")
    return ""


def evidence(members):
    """(sessions, days) across every member: session ids and dates in the Evidence section, plus the
    note's own date and last_observed."""
    sessions, days = set(), set()
    for inst in members:
        content = inst.get("content", "") or ""
        m = re.search(r"## Evidence\s*\n(.*?)(?:\n## |\Z)", content, re.S)
        body = m.group(1) if m else ""
        sessions |= {s.lower() for s in _SESSION.findall(body)}
        days |= set(_DAY.findall(body))
        for key in ("date", "last_observed"):
            if _DAY.fullmatch(str(inst.get(key, ""))):
                days.add(str(inst[key]))
    return sessions, days


def thin(members):
    """A reason when the evidence is under two sessions on two days, else ''. A lesson the user
    stated (`source: user-stated`) is the user's own words and is not held to session counts."""
    if members and all(str(m.get("source", "")) == "user-stated" for m in members):
        return ""
    sessions, days = evidence(members)
    if len(sessions) < MIN_SESSIONS or len(days) < MIN_DAYS:
        return (f"its evidence spans {len(sessions)} session(s) on {len(days)} day(s); "
                f"{MIN_SESSIONS} sessions on {MIN_DAYS} different days are needed")
    return ""


def _day_of(stamp):
    try:
        return datetime.fromisoformat(str(stamp).replace("Z", "+00:00")).date()
    except ValueError:
        return None


def dormant(project_ids, registry, today=None):
    """A reason when none of the projects was seen in the last ACTIVE_DAYS days, else ''. A lesson
    with no project (a global instinct) is not about a project and passes. A project the registry
    has no `last_seen` for is unknown, which is not recent: it does not count as active."""
    pids = [p for p in project_ids if p]
    if not pids:
        return ""
    today = today or date.today()
    seen = [_day_of((registry.get(p) or {}).get("last_seen", "")) for p in pids]
    if any(d is not None and (today - d).days <= ACTIVE_DAYS for d in seen):
        return ""
    known = [d for d in seen if d is not None]
    when = f"last activity {max(known).isoformat()}" if known else "no activity record"
    return f"none of its projects ({', '.join(sorted(pids))}) was active in the last {ACTIVE_DAYS} days ({when})"


def check(members, project_ids, corpus, registry, today=None, skip_labels=()):
    """Every failing reason for one candidate, in a fixed order. An empty list means it passes."""
    reasons = []
    hit = restates(_stems(" ".join(lesson_text(m) for m in members)), corpus, skip_labels)
    if hit:
        reasons.append(f"restates {hit[0]} (overlap {hit[1]:.2f} >= {OVERLAP_THRESHOLD})")
    for reason in (vague(members), thin(members), dormant(project_ids, registry, today)):
        if reason:
            reasons.append(reason)
    return reasons
